PTX_SOURCE = r'''
.version 7.1
.target sm_80
.address_size 64

.visible .entry cross_entropy_kernel(
    .param .u64 pred,
    .param .u64 target,
    .param .u64 loss,
    .param .u32 batch,
    .param .u32 classes
)
{
    //----- registers -------------------------------------------------
    .reg .pred .b64 %pred_ptr;
    .reg .pred .b64 %target_ptr;
    .reg .pred .b64 %loss_ptr;
    .reg .u32 %batch;
    .reg .u32 %classes;

    .reg .u32 %tid;
    .reg .u32 %bid;
    .reg .u32 %idx;

    .reg .u32 %i;
    .reg .pred .u32 %p0, %p1, %p2, %p3;

    .reg .f16 %val_f16;
    .reg .f32 %val_f32;
    .reg .f32 %max_val;
    .reg .f32 %sum_exp;
    .reg .f32 %exp_val;
    .reg .f32 %log_target;
    .reg .f32 %loss_f32;

    .reg .s64 %tgt;

    .reg .u64 %row_ptr;
    .reg .u64 %addr;
    .reg .u64 %loss_addr;
    .reg .u64 %target_addr;

    //----- load kernel parameters ------------------------------------
    ld.param.u64 %pred_ptr,   [pred];
    ld.param.u64 %target_ptr, [target];
    ld.param.u64 %loss_ptr,   [loss];
    ld.param.u32 %batch,      [batch];
    ld.param.u32 %classes,    [classes];

    //----- thread index ---------------------------------------------
    mov.u32 %tid, %tid.x;
    mov.u32 %bid, %ctaid.x;
    mad.lo.u32 %idx, %bid, %ntid.x, %tid;          // idx = blockIdx.x * blockDim.x + threadIdx.x

    setp.ge.u32 %p0, %idx, %batch;                // if idx >= batch -> exit
    @%p0 bra DONE;

    //----- pointers for this sample ---------------------------------
    // row base = pred_ptr + idx * classes * 2 (fp16 size)
    cvt.u64.u32 %row_ptr, %idx;
    mul.lo.u64 %row_ptr, %row_ptr, %classes;
    mul.lo.u64 %row_ptr, %row_ptr, 2;
    add.u64 %row_ptr, %pred_ptr, %row_ptr;

    // loss element address
    cvt.u64.u32 %loss_addr, %idx;
    mul.lo.u64 %loss_addr, %loss_addr, 2;
    add.u64 %loss_addr, %loss_ptr, %loss_addr;

    // target element address (int64)
    cvt.u64.u32 %target_addr, %idx;
    mul.lo.u64 %target_addr, %target_addr, 8;
    add.u64 %target_addr, %target_ptr, %target_addr;
    ld.global.s64 %tgt, [%target_addr];          // target class index (signed 64‑bit)

    //----- first pass: find max value -------------------------------
    mov.f32 %max_val, -1e20;                     // very small number
    mov.u32 %i, 0;
LOOP_MAX:
    setp.ge.u32 %p1, %i, %classes;
    @%p1 bra END_MAX;

    mul.lo.u64 %addr, %i, 2;                     // offset = i * 2
    add.u64 %addr, %row_ptr, %addr;
    ld.global.f16 %val_f16, [%addr];
    cvt.f32.f16 %val_f32, %val_f16;

    setp.gt.f32 %p2, %val_f32, %max_val;
    @%p2 mov.f32 %max_val, %val_f32;

    add.u32 %i, %i, 1;
    bra LOOP_MAX;
END_MAX:

    //----- second pass: sum of exp(logits - max) -------------------
    mov.f32 %sum_exp, 0f00000000;                // 0.0f
    mov.u32 %i, 0;
LOOP_SUM:
    setp.ge.u32 %p3, %i, %classes;
    @%p3 bra END_SUM;

    mul.lo.u64 %addr, %i, 2;
    add.u64 %addr, %row_ptr, %addr;
    ld.global.f16 %val_f16, [%addr];
    cvt.f32.f16 %val_f32, %val_f16;

    sub.f32 %val_f32, %val_f32, %max_val;        // logits - max
    // approximate exp (PTX provides exp.approx.f32)
    exp.approx.f32 %exp_val, %val_f32;
    add.f32 %sum_exp, %sum_exp, %exp_val;

    add.u32 %i, %i, 1;
    bra LOOP_SUM;
END_SUM:

    // log of denominator
    log.approx.f32 %sum_exp, %sum_exp;          // now %sum_exp = log(sum_exp)

    //----- fetch target logit ---------------------------------------
    cvt.u64.u32 %addr, %tgt;                     // target index as 64‑bit
    mul.lo.u64 %addr, %addr, 2;                  // *sizeof(fp16)
    add.u64 %addr, %row_ptr, %addr;
    ld.global.f16 %val_f16, [%addr];
    cvt.f32.f16 %log_target, %val_f16;

    // loss_i = -(log_target - max_val - log_sum)
    sub.f32 %loss_f32, %log_target, %max_val;
    sub.f32 %loss_f32, %loss_f32, %sum_exp;
    neg.f32 %loss_f32, %loss_f32;

    // store loss as fp16
    cvt.f16.f32 %val_f16, %loss_f32;
    st.global.f16 [%loss_addr], %val_f16;

DONE:
    ret;
}
'''

class ModelNew(torch.nn.Module):
    def __init__(self):
        super().__init__()
        self.module = ptx_load(PTX_SOURCE)

    def forward(self, predictions, targets):
        batch, num_classes = predictions.shape
        loss_buf = torch.empty(batch, dtype=torch.float16, device=predictions.device)

        grid_x = (batch + 255) // 256
        grid = (grid_x, 1, 1)
        block = (256, 1, 1)

        args = [
            predictions.data_ptr(),
            targets.data_ptr(),
            loss_buf.data_ptr(),
            batch,
            num_classes
        ]

        ptx_launch(self.module, "cross_entropy_kernel", grid, block, args)

        # Mean reduction to match torch.nn.functional.cross_entropy default behavior
        return loss_buf.mean()
